components.css:
.ds-btn { display:inline-flex; align-items:center; justify-content:center; gap:0.5rem; min-height:44px; padding:0 16px; border:2px solid var(--color-ink,#1d1c1a); border-radius:6px; font-family:"Archivo Variable", ui-sans-serif, system-ui, sans-serif; font-size:1rem; font-weight:600; font-stretch:112.5%; cursor:pointer; transition:color 150ms cubic-bezier(.4,0,.2,1), background-color 150ms cubic-bezier(.4,0,.2,1), border-color 150ms cubic-bezier(.4,0,.2,1); }
.ds-btn:focus-visible { outline:3px solid var(--color-ink,#1d1c1a); outline-offset:3px; }
.ds-btn--primary { background:var(--color-ink,#1d1c1a); color:var(--color-paper,#f2eee5); }
.ds-btn--primary:hover { background:var(--game-ink,#c8341b); color:var(--game-on-ink,#fff); }

.ds-btn { display:inline-flex; align-items:center; justify-content:center; gap:0.5rem; min-height:44px; padding:0 16px; border:2px solid var(--color-ink,#1d1c1a); border-radius:6px; background:transparent; color:var(--color-ink,#1d1c1a); font-family:"Archivo Variable", ui-sans-serif, system-ui, sans-serif; font-size:1rem; font-weight:600; font-stretch:112.5%; cursor:pointer; transition:background-color 150ms cubic-bezier(.4,0,.2,1); }
.ds-btn--secondary:hover { background:var(--color-paper-deep,#e6e0d2); }
.ds-btn:focus-visible { outline:3px solid var(--color-ink,#1d1c1a); outline-offset:3px; }

.ds-strip { display:flex; align-items:center; justify-content:space-between; gap:0.75rem; padding:10px 16px; background:var(--game-ink,#c8341b); color:var(--game-on-ink,#fff); border-top:2px solid var(--color-ink,#1d1c1a); font-family:"Archivo Variable", ui-sans-serif, system-ui, sans-serif; font-size:0.875rem; }
.ds-btn--paper { display:inline-flex; align-items:center; justify-content:center; min-height:36px; padding:0 16px; border:2px solid var(--color-paper,#f2eee5); border-radius:6px; background:var(--color-paper,#f2eee5); color:var(--color-ink,#1d1c1a); font-family:"Archivo Variable", ui-sans-serif, system-ui, sans-serif; font-size:0.875rem; font-weight:600; font-stretch:112.5%; cursor:pointer; transition:background-color 150ms cubic-bezier(.4,0,.2,1), border-color 150ms cubic-bezier(.4,0,.2,1); }
.ds-btn--paper:hover { background:var(--color-paper-deep,#e6e0d2); border-color:var(--color-paper-deep,#e6e0d2); }
.ds-btn--paper:focus-visible { outline:3px solid var(--color-paper,#f2eee5); outline-offset:3px; }

.ds-seg { display:flex; flex-wrap:wrap; align-items:center; gap:0 0.75rem; font-family:"Archivo Variable", ui-sans-serif, system-ui, sans-serif; }
.ds-seg__label { font-size:0.875rem; font-weight:600; color:var(--color-ink-muted,#6b665b); }
.ds-seg__group { display:inline-flex; padding:2px; border:2px solid var(--color-ink,#1d1c1a); border-radius:6px; }
.ds-seg__opt { display:inline-flex; align-items:center; min-height:32px; padding:0 10px; border:0; border-radius:3px; background:transparent; color:var(--color-ink,#1d1c1a); font-family:inherit; font-size:0.875rem; font-weight:600; cursor:pointer; transition:background-color 150ms cubic-bezier(.4,0,.2,1), color 150ms cubic-bezier(.4,0,.2,1); }
.ds-seg__opt:hover { background:var(--color-paper-deep,#e6e0d2); }
.ds-seg__opt.is-checked { background:var(--color-ink,#1d1c1a); color:var(--color-paper,#f2eee5); }
.ds-seg__opt:focus-visible { outline:3px solid var(--color-ink,#1d1c1a); outline-offset:2px; }

.ds-chips { display:flex; flex-wrap:wrap; gap:0.375rem; border:0; padding:0; font-family:"Archivo Variable", ui-sans-serif, system-ui, sans-serif; }
.ds-chips__legend { float:left; margin-right:0.75rem; font-size:0.875rem; font-weight:700; }
.ds-chip { position:relative; }
.ds-chip input { position:absolute; width:1px; height:1px; opacity:0; }
.ds-chip__face { display:inline-flex; align-items:center; min-height:40px; padding:0 12px; border:2px solid var(--color-ink,#1d1c1a); border-radius:6px; font-size:0.875rem; font-weight:600; cursor:pointer; transition:background-color 150ms cubic-bezier(.4,0,.2,1), color 150ms cubic-bezier(.4,0,.2,1); }
.ds-chip__face:hover { background:var(--color-paper-deep,#e6e0d2); }
.ds-chip__face.is-checked { background:var(--color-ink,#1d1c1a); color:var(--color-paper,#f2eee5); }
.ds-chip input:focus-visible + .ds-chip__face { outline:3px solid var(--color-ink,#1d1c1a); outline-offset:2px; }

.ds-lid { position:relative; display:flex; flex-direction:column; aspect-ratio:4/3; overflow:hidden; border-radius:6px; background:var(--game-ink,#c8341b); color:var(--game-on-ink,#fff); text-decoration:none; font-family:"Archivo Variable", ui-sans-serif, system-ui, sans-serif; transition:transform 200ms ease-out, box-shadow 200ms ease-out; }
.ds-lid:hover { transform:translateY(-4px); box-shadow:0 16px 28px -14px rgb(29 28 26 / 0.6); }
.ds-lid:focus-visible { outline:3px solid var(--color-ink,#1d1c1a); outline-offset:3px; }
.ds-lid__art { display:flex; flex:1 1 0; min-height:0; align-items:flex-start; justify-content:center; }
.ds-lid__foot { padding:0 5% 4.5%; }
.ds-lid__title { display:block; font-weight:900; font-stretch:125%; letter-spacing:-0.015em; line-height:0.98; font-size:clamp(0.9375rem, 7vw, 1.875rem); }
.ds-lid__meta { display:block; margin-top:0.35rem; font-weight:600; font-stretch:112.5%; font-size:clamp(0.6875rem, 3.6vw, 0.875rem); }
.ds-lid__stamp { position:absolute; top:4.5%; right:4.5%; transform:rotate(-6deg); border-radius:3px; background:var(--color-paper,#f2eee5); color:var(--color-ink,#1d1c1a); padding:0.55em 0.6em; font-size:clamp(0.625rem, 3.4vw, 0.8125rem); font-weight:900; font-stretch:125%; letter-spacing:0.05em; text-transform:uppercase; font-variant-numeric:tabular-nums; box-shadow:inset 0 0 0 2px var(--color-ink,#1d1c1a), inset 0 0 0 3.5px var(--color-paper,#f2eee5), inset 0 0 0 4.5px var(--color-ink,#1d1c1a); }

.ds-frame { overflow:hidden; border:2px solid var(--color-ink,#1d1c1a); border-radius:6px; background:var(--color-card,#fbf9f4); color:var(--color-ink,#1d1c1a); font-family:"Archivo Variable", ui-sans-serif, system-ui, sans-serif; }
.ds-frame__top { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:0.75rem; padding:10px 16px; border-bottom:2px solid var(--color-ink,#1d1c1a); }
.ds-frame__stats { display:flex; gap:1rem; margin:0; }
.ds-frame__stats dt { font-size:0.75rem; font-weight:600; text-transform:uppercase; letter-spacing:0.025em; color:var(--color-ink-muted,#6b665b); }
.ds-frame__stats dd { margin:0; font-size:1rem; font-weight:700; font-variant-numeric:tabular-nums; }
.ds-frame__board { padding:16px 20px; }
.ds-board { width:min(100%, 22rem); aspect-ratio:1; margin:0 auto; border:2px solid var(--color-ink,#1d1c1a); border-radius:6px; background:var(--color-paper,#f2eee5); }
.ds-frame__strip { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:0.75rem; padding:10px 16px; border-top:2px solid var(--color-ink,#1d1c1a); }
.ds-frame__strip p { margin:0; font-size:0.875rem; }
.ds-seg__group { display:inline-flex; padding:2px; border:2px solid var(--color-ink,#1d1c1a); border-radius:6px; }
.ds-seg__opt { display:inline-flex; align-items:center; min-height:32px; padding:0 10px; border:0; border-radius:3px; background:transparent; color:var(--color-ink,#1d1c1a); font:inherit; font-size:0.875rem; font-weight:600; cursor:pointer; }
.ds-seg__opt.is-checked { background:var(--color-ink,#1d1c1a); color:var(--color-paper,#f2eee5); }
.ds-btn--primary { display:inline-flex; align-items:center; min-height:36px; padding:0 16px; border:2px solid var(--color-ink,#1d1c1a); border-radius:6px; background:var(--color-ink,#1d1c1a); color:var(--color-paper,#f2eee5); font:inherit; font-size:0.875rem; font-weight:600; cursor:pointer; }

.ds-callout { margin:2rem 0; padding:16px 20px; border:2px solid var(--color-ink,#1d1c1a); border-radius:6px; background:var(--color-paper-deep,#e6e0d2); color:var(--color-ink,#1d1c1a); }
.ds-callout__title { margin:0; font-family:"Archivo Variable", ui-sans-serif, system-ui, sans-serif; font-size:1rem; font-weight:800; font-stretch:125%; line-height:1.3; }
.ds-callout__body { margin-top:0.5rem; font-family:"Source Serif 4 Variable", ui-serif, Georgia, serif; font-size:1.0625rem; line-height:1.7; }
.ds-callout__body p { margin:0.5rem 0; }

.ds-tile { display:flex; flex-direction:column; justify-content:flex-end; aspect-ratio:4/3; padding:5%; border:2px dashed var(--color-ink,#1d1c1a); border-radius:6px; background:var(--color-paper,#f2eee5); color:var(--color-ink,#1d1c1a); text-decoration:none; font-family:"Archivo Variable", ui-sans-serif, system-ui, sans-serif; transition:border-color 150ms cubic-bezier(.4,0,.2,1), background-color 150ms cubic-bezier(.4,0,.2,1), border-style 150ms linear; }
.ds-tile:hover { border-style:solid; background:var(--color-paper-deep,#e6e0d2); }
.ds-tile:focus-visible { outline:3px solid var(--color-ink,#1d1c1a); outline-offset:3px; }
.ds-tile__title { font-weight:900; font-stretch:125%; letter-spacing:-0.015em; line-height:0.98; font-size:clamp(0.9375rem, 6.5vw, 1.625rem); }
.ds-tile__row { display:flex; align-items:flex-end; justify-content:space-between; gap:0.5rem; margin-top:0.4rem; font-size:clamp(0.75rem, 3.6vw, 0.9375rem); color:var(--color-ink-soft,#4e4a42); }
